from pathlib import Path
import base64, io
from PIL import Image
r=Path(__file__).resolve().parent.parent

def data_img(path,max_w=1400):
 im=Image.open(r/'public/images'/path).convert('RGB')
 if im.width>max_w: im.thumbnail((max_w,max_w*10),Image.Resampling.LANCZOS)
 buf=io.BytesIO();im.save(buf,format='WEBP',quality=78,method=6)
 return 'data:image/webp;base64,'+base64.b64encode(buf.getvalue()).decode()
hero=data_img('hero.webp',1400)
names=['origen','patio','horizonte','linea'];areas=[90,120,150,180]
models=''.join(f'''<div class="model" data-area="{area}"><img loading="lazy" src="{data_img(f'{name}-fachada.webp',760)}" alt="Render conceptual de la estructura {area} m² sin acabados"><div class="pad"><div class="minor">CONCEPTO {i+1:02} / ESTRUCTURA EN BRUTO</div><div class="modelrow"><h3>BLOQUE {area}</h3><b>{area*700:,.0f} €</b></div><div class="small">{area} m² · Solo kit · Sin transporte</div><button type="button" onclick="setArea({area});location.hash='calculadora'">CONFIGURAR ↗</button></div></div>''' for i,(name,area) in enumerate(zip(names,areas)))
